ype'', CAST(json_extract_scalar(vcattribs, ''$.acceptanceType'') AS VARCHAR)), ROW(''Verified AccountName'', CAST(json_extract_scalar(vcattribs, ''$.sellerVerifiedAccountName'') AS VARCHAR)), ROW(''Daily Transaction Value'', CAST(json_extract_scalar(vcattribs, ''$.dailyTransactionValue'') AS VARCHAR)), ROW(''Daily Transaction Volume'', CAST(json_extract_scalar(vcattribs, ''$.dailyTransactionVolume'') AS VARCHAR)), ROW(''Cumulative Daily Transaction Volume'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyTransactionVolume'') AS VARCHAR)), ROW(''Cumulative Daily Transaction Count'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyTransactionCount'') AS VARCHAR)), ROW(''Cumulative Daily Transaction Exit Volume'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyTransactionExitVolume'') AS VARCHAR)), ROW(''Cumulative Daily Refund Volume'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyRefundVolume'') AS VARCHAR)), ROW(''Business Channel'', CAST(json_extract_scalar(vcattribs, ''$.businessChannel'') AS VARCHAR)), ROW(''Group ID'', CAST(json_extract_scalar(vcattribs, ''$.groupId'') AS VARCHAR)), ROW(''Sub-Group ID'', CAST(json_extract_scalar(vcattribs, ''$.subGroupId'') AS VARCHAR)), ROW(''Cumulative Daily Refund Count'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyRefundCount'') AS VARCHAR)), ROW(''Cumulative Daily Refund Exit Volume'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyRefundExitVolume'') AS VARCHAR)), ROW(''Cumulative Daily Refund Exit Count'', CAST(json_extract_scalar(vcattribs, ''$.cumulativeDailyRefundExitCount'') AS VARCHAR)), ROW(''Business Legal Name'', CAST(json_extract_scalar(vcattribs, ''$.business_legal_name'') AS VARCHAR)), ROW(''Date of Incorporation'', CAST(json_extract_scalar(vcattribs, ''$.date_of_incorporation'') AS VARCHAR)), ROW(''GST Business Type'', CAST(json_extract_scalar(vcattribs, ''$.business_type'') AS VARCHAR)), ROW(''GST Business Division'', CAST(json_extract_scalar(vcattribs, ''$