rstName'') AS VARCHAR)), ROW(''Middle Name - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_middleName'') AS VARCHAR)), ROW(''Last Name - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_lastName'') AS VARCHAR)), ROW(''Registered Mobile - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_registered_mobile'') AS VARCHAR)), ROW(''Email - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_email'') AS VARCHAR)), ROW(''Address Line 1 - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_address_line1'') AS VARCHAR)), ROW(''Address Line 2 - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_address_line2'') AS VARCHAR)), ROW(''State - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_state'') AS VARCHAR)), ROW(''City - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_city'') AS VARCHAR)), ROW(''Country - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_country'') AS VARCHAR)), ROW(''Postal Code - Authorized Signatory'', CAST(json_extract_scalar(vcattribs, ''$.auth_sign_postal_code'') AS VARCHAR)), ROW(''Program Category'', CAST(json_extract_scalar(vcattribs, ''$.program_category'') AS VARCHAR)), ROW(''Program Reference ID'', CAST(json_extract_scalar(vcattribs, ''$.program_referenceID'') AS VARCHAR)), ROW(''Merchant Bank Name'', CAST(json_extract_scalar(vcattribs, ''$.merchantBankName'') AS VARCHAR)), ROW(''Business Category'', CAST(json_extract_scalar(vcattribs, ''$.businessCategory'') AS VARCHAR)), ROW(''Business Line'', CAST(json_extract_scalar(vcattribs, ''$.businessLine'') AS VARCHAR)), ROW(''Settlement Frequency'', CAST(json_extract_scalar(vcattribs, ''$.settlementFrequency'') AS VARCHAR)), ROW(''MID Blocked Date'', CAST(json_extract_scalar(vcattribs, ''$.mid_BlockedDate'') AS VARCHAR)), ROW(''MID Blocked By'', CAST(json_extract_scalar(vcattribs, ''$.mi